  it('T1-THET-06: ambient glow toggle inverts current glow state', () => {
    expect(useAppStore.getState().ambientGlow).toBe(true);
    useAppStore.getState().toggleAmbientGlow();
    expect(useAppStore.getState().ambientGlow).toBe(false);
  });
});

ml_engine.frame_engine_full:
import { FrameAspectRatio, FrameReframeMode } from '../../types';

/**
 * CineMorph AI - Smart Framing & Viewport Adaptation Engine
 */

export interface FrameStyleResult {
  containerAspectClass: string;
  aspectRatioStyle: string;
  videoScaleTransform: string;
  cropOverlay: boolean;
  paddingTop: string;
}

export function calculateFrameStyle(
  aspectRatio: FrameAspectRatio,
  reframeMode: FrameReframeMode
): FrameStyleResult {
  let paddingTop = '56.25%'; // Default 16:9 ratio
  let videoScaleTransform = 'scale(1.0) translate(0px, 0px)';
  let cropOverlay = false;
  let aspectRatioStyle = '16 / 9';

  switch (aspectRatio) {
    case 'original':
      paddingTop = '56.25%';
      aspectRatioStyle = '16 / 9';
      videoScaleTransform = 'scale(1.0) translate(0px, 0px)';
      cropOverlay = false;
      break;

    case 'auto':
      paddingTop = '48%';
      aspectRatioStyle = '19.5 / 9';
      videoScaleTransform = 'scale(1.18) translateY(-3%)';
      cropOverlay = true;
      break;

    case '21:9':
      paddingTop = '42.85%';
      aspectRatioStyle = '21 / 9';
      if (reframeMode === 'center') {
        videoScaleTransform = 'scale(1.33) translateY(0%)';
      } else if (reframeMode === 'face-priority') {
        videoScaleTransform = 'scale(1.35) translateY(-4%)';
      } else if (reframeMode === 'smart-pan-zoom') {
        videoScaleTransform = 'scale(1.42) translateY(2%)';
      } else {
        videoScaleTransform = 'scale(1.33) translateY(-2%)';
      }
      cropOverlay = true;
      break;

    case '4:3':
      paddingTop = '75%';
      aspectRatioStyle = '4 / 3';
      if (reframeMode === 'face-priority') {
        videoScaleTransform = 'scale(1.12) translateY(-2%)';
      } else if (reframeMode === 'smart-pan-zoom') {
        videoScaleTransform = 'scale(1.20)';
      } else {
        videoScaleTransform = 'scale(1.0)';
      }
      break;

    case '1:1':
      paddingTop = '100%';
      aspectRatioStyle = '1 / 1';
      videoScaleTransform = 'scale(1.35) translateY(-3%)';
      cropOverlay = true;
      break;

    case '1.43:1':
      paddingTop = '69.93%';
      aspectRatioStyle = '143 / 100';
      if (reframeMode === 'face-priority') {
        videoScaleTransform = 'scale(1.28) translateY(-3%)';
      } else if (reframeMode === 'smart-pan-zoom') {
        videoScaleTransform = 'scale(1.32) translateY(-2%)';
      } else {
        videoScaleTransform = 'scale(1.25) translateY(0%)';
      }
      cropOverlay = true;
      break;

    case '1.90:1':
      paddingTop = '52.63%';
      aspectRatioStyle = '190 / 100';
      if (reframeMode === 'face-priority') {
        videoScaleTransform = 'scale(1.12) translateY(-2%)';
      } else if (reframeMode === 'smart-pan-zoom') {
        videoScaleTransform = 'scale(1.16) translateY(-1%)';
      } else {
        videoScaleTransform = 'scale(1.08) translateY(0%)';
      }
      cropOverlay = true;
      break;

    case '4.3:1':
      paddingTop = '23.255%';
      aspectRatioStyle = '43 / 10';
      if (reframeMode === 'face-priority') {
        videoScaleTransform = 'scale(1.45) translateY(-5%)';
      } else {
        videoScaleTransform = 'scale(1.35) translateY(-2%)';
      }
      cropOverlay = true;
      break;

    case '16:9':
    default:
      paddingTop = '56.25%';
      aspectRatioStyle = '16 / 9';
      if (reframeMode === 'face-priority') {
        videoScaleTransform = 'scale(1.06) translateY(-2%)';
      } else if (reframeMode === 'smart-pan-zoom') {
        videoScaleTransform = 'scale(1.12) translateY(0%)';
      } else {
        videoScaleTransform = 'scale(1.0)';
      }
      break;
  }

  return {
    containerAspectClass: 
      aspectRatio === 'original' ? 'aspect-video' :
      aspectRatio === 'auto' ? 'aspect-[19.5/9]' :
      aspectRatio === '1.43:1' ? 'aspect-[143/100]' :
      aspectRatio === '1.90:1' ? 'aspect-[190/100]' :
      aspectRatio === '21:9' ? 'aspect-[21/9]' : 
      aspectRatio === '4:3' ? 'aspect-[4/3]' : 
      aspectRatio === '1:1' ? 'aspect-square' : 
      aspectRatio === '4.3:1' ? 'aspect-[43/10]' : 'aspect-video',
    aspectRatioStyle,
    videoScaleTransform,
    cropOverlay,
    paddingTop,
  };
}

ml_engine.local_analyzer_full:
import { LocalVideoAnalysis } from '../../types';

/**
 * LocalVideoAnalyzer
 * Real client-side canvas-based frame and scene analysis for personal local video files.
 * Zero-upload, zero-cost, runs completely inside the browser.
 */
export class LocalVideoAnalyzer {
  private canvas: HTMLCanvasElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private lastHistogram: number[] | null = null;
  private cacheMap = new Map<string, LocalVideoAnalysis>();

  constructor() {
    if (typeof document !== 'undefined') {
      this.canvas = document.createElement('canvas');
      this.canvas.width = 16;  // 16x9 ultra-fast sample grid (144 pixels for zero CPU overhead)
      this.canvas.height = 9;
      this.ctx = this.canvas.getContext('2d', { willReadFrequently: true });
    }
  }

  public getCachedAnalysis(key: string): LocalVideoAnalysis | undefined {
    return this.cacheMap.get(key);
  }

  /**
   * Analyzes an active HTML5 Video Element frame
   */
  public analyzeVideoFrame(videoEl: HTMLVideoElement, fileKey?: string): LocalVideoAnalysis | null {
    if (!this.ctx || !this.canvas || videoEl.readyState < 2 || videoEl.videoWidth === 0) {
      return null;
    }

    try {
      this.ctx.drawImage(videoEl, 0, 0, this.canvas.width, this.canvas.height);
      const imgData = this.ctx.getImageData(0, 0, this.canvas.width, this.canvas.height);
      const data = imgData.data;
      const totalPixels = this.canvas.width * this.canvas.height;

      let rSum = 0;
      let gSum = 0;
      let bSum = 0;
      let totalBrightness = 0;

      // 16-bin luminance histogram for scene change detection
      const histogram = new Array(16).fill(0);

      // Saliency edge accumulator
      let weightedX = 0;
      let totalWeight = 0;

      for (let i = 0; i < data.length; i += 4) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const lum = Math.round(0.299 * r + 0.587 * g + 0.114 * b);

        rSum += r;
        gSum += g;
        bSum += b;
        totalBrightness += lum;

        const bin = Math.min(15, Math.floor(lum / 16));
        histogram[bin]++;

        // Pixel X index
        const px = (i / 4) % this.canvas.width;
        // Weight by high contrast / luminance variation
        const weight = Math.abs(lum - 128);
        weightedX += px * weight;
        totalWeight += weight;
      }

      const avgR = Math.round(rSum / totalPixels);
      const avgG = Math.round(gSum / totalPixels);
      const avgB = Math.round(bSum / totalPixels);
      const avgBrightness = Math.round(totalBrightness / totalPixels);

      // Scene change calculation (histogram delta)
      let sceneChangeDetected = false;
      if (this.lastHistogram) {
        let diff = 0;
        for (let i = 0; i < 16; i++) {
          diff += Math.abs(this.lastHistogram[i] - histogram[i]);
        }
        const deltaRatio = diff / totalPixels;
        if (deltaRatio > 0.45) {
          sceneChangeDetected = true;
        }
      }
      this.lastHistogram = histogram;

      const saliencyCenterX = totalWeight > 0 
        ? Math.max(0.1, Math.min(0.9, (weightedX / totalWeight) / this.canvas.width)) 
        : 0.5;

      const dominantColor = `rgb(${avgR}, ${avgG}, ${avgB})`;
      const secondaryColor = `rgb(${Math.min(255, avgR + 30)}, ${Math.max(0, avgG - 20)}, ${Math.min(255, avgB + 40)})`;

      const result: LocalVideoAnalysis = {
        avgBrightness,
        dominantColor,
        secondaryColor,
        sceneChangeDetected,
        saliencyCenterX,
        contrastScore: Math.round((totalWeight / (totalPixels * 128)) * 100),
        timestamp: Date.now(),
      };

      if (fileKey) {
        this.cacheMap.set(fileKey, result);
      }

      return result;
    } catch (err) {
      return null;
    }
  }

  public analyzeVideoFrameWithKey(videoEl: HTMLVideoElement, fileKey?: string): LocalVideoAnalysis | null {
    return this.analyzeVideoFrame(videoEl, fileKey);
  }

  public reset(): void {
    this.lastHistogram = null;
  }
}

export const localVideoAnalyzer = new LocalVideoAnalyzer();

ml_engine.hybrid_pipeline_full:
/**
 * Hybrid Intelligence Pipeline & Temporal Smoothing Engine
 * Provides stable cinematic viewport tracking with zero visual jitter.
 */

export interface FrameCompositionAnalysis {
  focalPointX: number; // 0.0 (left) to 1.0 (right)
  focalPointY: number; // 0.0 (top) to 1.0 (bottom)
  confidence: number;  // 0.0 to 1.0
  recommendedAspect: '16:9' | '21:9' | '4:3' | '1:1';
  pipelineStage: 'FAST_PATH' | 'BALANCED_PATH' | 'FALLBACK';
}

export class HybridIntelligencePipeline {
  private static previousFocalX = 0.5;
  private static previousFocalY = 0.5;
  private static smoothingFactor = 0.15; // Exponential Moving Average (EMA) alpha
  private static minConfidenceThreshold = 0.60;

  /**
   * Analyzes scene composition and calculates smoothed focal coordinates
   */
  public static analyzeFrame(
    canvasWidth: number,
    canvasHeight: number,
    sampleLuminanceGrid?: number[]
  ): FrameCompositionAnalysis {
    try {
      if (!sampleLuminanceGrid || sampleLuminanceGrid.length === 0) {
        return this.getNeutralFallback();
      }

      // Fast Path: Saliency Grid Weighted Average
      let totalWeight = 0;
      let weightedX = 0;
      let weightedY = 0;
      const gridSize = Math.sqrt(sampleLuminanceGrid.length);

      for (let i = 0; i < sampleLuminanceGrid.length; i++) {
        const row = Math.floor(i / gridSize);
        const col = i % gridSize;
        const weight = sampleLuminanceGrid[i];

        weightedX += (col / gridSize) * weight;
        weightedY += (row / gridSize) * weight;
        totalWeight += weight;
      }

      if (totalWeight === 0) {
        return this.getNeutralFallback();
      }

      const rawFocalX = weightedX / totalWeight;
      const rawFocalY = weightedY / totalWeight;
      const confidence = Math.min(1.0, totalWeight / (sampleLuminanceGrid.length * 128));

      // Confidence Guardrail: Fallback if confidence is too low
      if (confidence < this.minConfidenceThreshold) {
        return {
          focalPointX: this.previousFocalX,
          focalPointY: this.previousFocalY,
          confidence,
          recommendedAspect: '21:9',
          pipelineStage: 'FALLBACK',
        };
      }

      // Temporal Hysteresis & Exponential Smoothing
      const smoothedX = this.previousFocalX + this.smoothingFactor * (rawFocalX - this.previousFocalX);
      const smoothedY = this.previousFocalY + this.smoothingFactor * (rawFocalY - this.previousFocalY);

      this.previousFocalX = Math.max(0.1, Math.min(0.9, smoothedX));
      this.previousFocalY = Math.max(0.1, Math.min(0.9, smoothedY));

      return {
        focalPointX: this.previousFocalX,
        focalPointY: this.previousFocalY,
        confidence,
        recommendedAspect: '21:9',
        pipelineStage: 'BALANCED_PATH',
      };
    } catch (err) {
      return this.getNeutralFallback();
    }
  }

  public static resetTemporalBuffer(): void {
    this.previousFocalX = 0.5;
    this.previousFocalY = 0.5;
  }

  private static getNeutralFallback(): FrameCompositionAnalysis {
    return {
      focalPointX: 0.5,
      focalPointY: 0.5,
      confidence: 1.0,
      recommendedAspect: '16:9',
      pipelineStage: 'FALLBACK',
    };
  }
}

