              </div>
              <div className="space-y-1 text-center">
                <div className="text-sm font-bold text-white">
                  Drop your local video or audio file here, or <span className="text-cyan-400 underline underline-offset-2">Browse</span>
                </div>
                <div className="text-xs text-gray-400">
                  Supports MP4, MKV, WebM, MOV, AVI, FLV, TS, MP3, WAV, AAC, FLAC & All Formats
                </div>
              </div>
            </div>

            {/* Error Message */}
            {localFileError && (
              <div className="max-w-xl mx-auto p-3 rounded-xl bg-red-500/15 border border-red-500/30 text-red-300 text-xs font-semibold flex items-center justify-between">
                <span>{localFileError}</span>
                <button onClick={() => setLocalFileError(null)}><X className="w-4 h-4" /></button>
              </div>
            )}

            {/* Recent Local Media Sessions (Premium Cards Grid) */}
            {recentLocalList.length > 0 ? (
              <div className="space-y-4 pt-4 max-w-xl mx-auto text-left">
                <div className="flex items-center justify-between text-xs text-gray-400 px-1 font-bold uppercase tracking-widest">
                  <span>Recent Cinema Sessions</span>
                  <span className="text-[10px] text-cyan-400">Click to Resume Playback</span>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {recentLocalList.map((item) => {
                    const progressPercent = item.duration > 0 ? (item.progress / item.duration) * 100 : 0;
                    return (
                      <div
                        key={item.id}
                        onClick={() => {
                          if (item.url) {
                            setActiveLocalMedia(item);
                            navigate(`/watch/${item.id}`);
                          } else {
                            fileInputRef.current?.click();
                          }
                        }}
                        className="group relative rounded-2xl bg-[#0b0a12]/80 hover:bg-[#12101e] border border-white/5 hover:border-cyan-500/40 p-4 cursor-pointer transition-all duration-300 flex flex-col justify-between h-32 hover:scale-[1.02] shadow-lg overflow-hidden"
                      >
                        {/* Ambient corner indicator */}
                        <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-cyan-500/5 to-transparent rounded-full blur-xl pointer-events-none" />

                        <div className="flex items-start gap-3">
                          <div className="w-12 h-12 rounded-xl bg-cyan-950/40 border border-cyan-500/20 flex items-center justify-center text-cyan-400 shrink-0 group-hover:scale-105 transition-transform">
                            <FileVideo className="w-6 h-6" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="text-xs font-bold text-gray-200 group-hover:text-white truncate">
                              {item.name}
                            </div>
                            <div className="text-[10px] text-gray-400 pt-0.5 font-semibold">
                              {(item.size / (1024 * 1024)).toFixed(1)} MB • {item.type.split('/')[1].toUpperCase()}
                            </div>
                          </div>
                        </div>

                        <div className="space-y-2">
                          {/* Progress bar */}
                          {item.duration > 0 && (
                            <div className="space-y-1">
                              <div className="w-full bg-white/10 h-1 rounded-full overflow-hidden">
                                <div 
                                  className="bg-gradient-to-r from-cyan-500 to-indigo-500 h-full rounded-full"
                                  style={{ width: `${progressPercent}%` }}
                                />
                              </div>
                              <div className="flex justify-between text-[9px] text-gray-500 font-mono">
                                <span>{Math.round(progressPercent)}% watched</span>
                                <span>{Math.floor(item.duration / 60)} min</span>
                              </div>
                            </div>
                          )}

                          <div className="text-[10px] text-cyan-400 font-bold tracking-wider uppercase flex items-center gap-1 group-hover:text-cyan-300">
                            <span>Resume theater</span>
                            <ChevronRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ) : (
              <div className="max-w-xl mx-auto p-8 rounded-3xl bg-[#0a0812]/40 border border-white/5 text-center space-y-2">
                <FolderHeart className="w-8 h-8 text-gray-600 mx-auto" />
                <div className="text-xs font-semibold text-gray-400">No recent local media sessions found</div>
                <p className="text-[10px] text-gray-500">Drag or browse a video file to begin watching privately.</p>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Footer System Diagnostics */}
      <div className="w-full max-w-6xl flex flex-col sm:flex-row items-center justify-between gap-3 z-10 pt-4 border-t border-white/5 text-xs text-gray-500">
        <div className="flex items-center gap-2">
          <span>CineMorph Virtual Theater Architecture</span>
          <span>•</span>
          <span>Zero-Latency Media Pipeline</span>
        </div>
        <div className="flex items-center gap-2 text-emerald-400">
          <ShieldCheck className="w-4 h-4" />
          <span>Private Client-Side Execution</span>
        </div>
      </div>
    </div>
  );
}

audio_engine.ticket_test_full:
import { describe, it, expect, beforeEach } from 'vitest';
import { createTicketStore } from '../helpers/contracts';

describe('Tier 1: 10s Ticket Printer Animation & Heads-Up Processing (F31, F32, F33)', () => {
  let store: ReturnType<typeof createTicketStore>;

  beforeEach(() => {
    store = createTicketStore();
  });

  it('T1-TCKT-01: triggering print animation activates isPrintingAnimationActive state', async () => {
    expect(store.getState().isPrintingAnimationActive).toBe(false);

    const animationPromise = store.getState().trigger10sPrintAnimation({
      title: 'Interstellar',
      source: 'local-file-123',
      isLocal: true,
    });

    expect(store.getState().isPrintingAnimationActive).toBe(true);
    await animationPromise;
    expect(store.getState().isPrintingAnimationActive).toBe(false);
  });

  it('T1-TCKT-02: heads-up processing warmup completes without unhandled errors', async () => {
    const movieData = {
      title: 'Dune Part Two',
      source: 'https://youtube.com/watch?v=dQw4w9WgXcQ',
      isLocal: false,
    };

    let completed = false;
    await store.getState().trigger10sPrintAnimation(movieData).then(() => {
      completed = true;
    });

    expect(completed).toBe(true);
    expect(store.getState().isPrintingAnimationActive).toBe(false);
  });

  it('T1-TCKT-03: multiple concurrent animation triggers resolve cleanly', async () => {
    const p1 = store.getState().trigger10sPrintAnimation({ title: 'Movie A', source: 'a', isLocal: true });
    const p2 = store.getState().trigger10sPrintAnimation({ title: 'Movie B', source: 'b', isLocal: false });

    await Promise.all([p1, p2]);
    expect(store.getState().isPrintingAnimationActive).toBe(false);
  });

  it('T1-TCKT-04: ticket animation duration behaves deterministically across calls', async () => {
    const startTime = Date.now();
    await store.getState().trigger10sPrintAnimation({ title: 'Test Movie', source: 'test', isLocal: true });
    const elapsed = Date.now() - startTime;
    expect(elapsed).toBeGreaterThanOrEqual(0);
  });

  it('T1-TCKT-05: active ticket state remains accessible after animation completes', async () => {
    const ticketId = store.getState().saveTicketProgress({
      movieTitle: 'Blade Runner 2049',
      sourceUrl: 'local-br2049',
      isLocal: true,
      aspectRatio: '1.43:1',
      framingRule: 'rule_of_thirds',
      timestampSeconds: 1200,
      durationSeconds: 9800,
    });

    await store.getState().trigger10sPrintAnimation({ title: 'Blade Runner 2049', source: 'local-br2049', isLocal: true });
    expect(store.getState().activeTicket?.ticketId).toBe(ticketId);
  });
});

audio_engine.resume_test_full:
import { describe, it, expect, beforeEach } from 'vitest';
import { createTicketStore } from '../helpers/contracts';

describe('Tier 1: Torn Ticket Save & 1-Click Resume (F34, F35)', () => {
  let store: ReturnType<typeof createTicketStore>;

  beforeEach(() => {
    store = createTicketStore();
  });

  it('T1-RESM-01: saveTicketProgress generates a valid ticketId and stores progress metadata', () => {
    expect(store.getState().tickets).toHaveLength(0);

    const ticketId = store.getState().saveTicketProgress({
      movieTitle: 'Oppenheimer',
      sourceUrl: 'local-oppenheimer-imax',
      isLocal: true,
      aspectRatio: '1.43:1',
      framingRule: 'rule_of_thirds',
      timestampSeconds: 3420,
      durationSeconds: 10800,
    });

    expect(ticketId).toBeDefined();
    expect(ticketId).toMatch(/^ticket-/);
    expect(store.getState().tickets).toHaveLength(1);
    expect(store.getState().tickets[0].timestampSeconds).toBe(3420);
  });

  it('T1-RESM-02: resumeFromTicket restores the exact timestamp and settings of the target ticket', () => {
    const ticketId = store.getState().saveTicketProgress({
      movieTitle: 'Inception',
      sourceUrl: 'local-inception',
      isLocal: true,
      aspectRatio: '1.90:1',
      framingRule: 'leading_lines',
      timestampSeconds: 5200,
      durationSeconds: 8800,
    });

    const resumed = store.getState().resumeFromTicket(ticketId);
    expect(resumed).not.toBeNull();
    expect(resumed?.movieTitle).toBe('Inception');
    expect(resumed?.timestampSeconds).toBe(5200);
    expect(resumed?.aspectRatio).toBe('1.90:1');
  });

  it('T1-RESM-03: resuming with invalid/non-existent ticketId returns null safely', () => {
    const result = store.getState().resumeFromTicket('non-existent-ticket-id');
    expect(result).toBeNull();
  });

  it('T1-RESM-04: removeTicket deletes ticket by ID from state', () => {
    const t1 = store.getState().saveTicketProgress({
      movieTitle: 'Tenet',
      sourceUrl: 'local-tenet',
      isLocal: true,
      aspectRatio: '1.43:1',
      framingRule: 'auto',
      timestampSeconds: 100,
      durationSeconds: 9000,
    });
    const t2 = store.getState().saveTicketProgress({
      movieTitle: 'Dunkirk',
      sourceUrl: 'local-dunkirk',
      isLocal: true,
      aspectRatio: '1.43:1',
      framingRule: 'auto',
      timestampSeconds: 200,
      durationSeconds: 6000,
    });

    expect(store.getState().tickets).toHaveLength(2);
    store.getState().removeTicket(t1);
    expect(store.getState().tickets).toHaveLength(1);
    expect(store.getState().tickets[0].ticketId).toBe(t2);
  });

  it('T1-RESM-05: saving progress for the same movie updates existing ticket rather than duplicating', () => {
    store.getState().saveTicketProgress({
      movieTitle: 'Interstellar',
      sourceUrl: 'local-interstellar',
      isLocal: true,
      aspectRatio: '1.43:1',
      framingRule: 'auto',
      timestampSeconds: 1500,
      durationSeconds: 10000,
    });

    store.getState().saveTicketProgress({
      movieTitle: 'Interstellar',
      sourceUrl: 'local-interstellar',
      isLocal: true,
      aspectRatio: '1.43:1',
      framingRule: 'auto',
      timestampSeconds: 4500,
      durationSeconds: 10000,
    });

    expect(store.getState().tickets).toHaveLength(1);
    expect(store.getState().tickets[0].timestampSeconds).toBe(4500);
  });
});

storage.storage_service_full:
/**
 * OmniStream Dual-Tier Storage Service
 * 
 * Provides robust LocalStorage & IndexedDB persistence with:
 * 1. Resilient JSON parsing with automatic corrupt data backup and fallback recovery.
 * 2. QuotaExceededError eviction mitigation.
 * 3. In-Memory fallback store for incognito or restricted browser environments.
 * 4. Async IndexedDB object stores for heavy ticket thumbnails, offline cache, and media metadata.
 */

const DB_NAME = 'omnistream-db';
const DB_VERSION = 1;

export const IDB_STORES = {
  TICKETS: 'tickets',
  OFFLINE_VIDEOS: 'offline_videos',
  MEDIA_BLOBS: 'media_blobs',
  METADATA: 'metadata',
} as const;

export type IDBStoreName = typeof IDB_STORES[keyof typeof IDB_STORES];

class StorageService {
  private memoryFallback: Map<string, any> = new Map();
  private dbPromise: Promise<IDBDatabase | null> | null = null;

  private get localStorage(): Storage | null {
    try {
      if (typeof window !== 'undefined' && window.localStorage && typeof window.localStorage.getItem === 'function') {
        return window.localStorage;
      }
      if (typeof globalThis !== 'undefined' && (globalThis as any).localStorage && typeof (globalThis as any).localStorage.getItem === 'function') {
        return (globalThis as any).localStorage;
      }
    } catch {
      return null;
    }
    return null;
  }

  // ==========================================
  // Synchronous LocalStorage Tier with Auto-Repair
  // ==========================================

  public getLocal<T>(key: string, fallbackValue: T): T {
    const ls = this.localStorage;
    if (!ls) {
      return this.memoryFallback.has(key) ? (this.memoryFallback.get(key) as T) : fallbackValue;
    }

    try {
      const raw = ls.getItem(key);
      if (raw === null || raw === undefined) {
        return fallbackValue;
      }

      return JSON.parse(raw) as T;
    } catch (parseError) {
      console.warn(`[StorageService] Corrupt JSON detected for key "${key}". Initiating auto-repair...`, parseError);
      this.autoRepairCorruptLocalKey(key);
      return fallbackValue;
    }
  }

  public setLocal<T>(key: string, value: T): boolean {
    const ls = this.localStorage;
    if (!ls) {
      this.memoryFallback.set(key, value);
      return true;
    }

    try {
      const serialized = JSON.stringify(value);
      ls.setItem(key, serialized);
      return true;
    } catch (err: any) {
      if (err?.name === 'QuotaExceededError' || err?.code === 22 || err?.number === -2147024882) {
        console.warn('[StorageService] LocalStorage quota exceeded. Evicting temporary caches and retrying...');
        this.evictTemporaryCaches();
        try {
          ls.setItem(key, JSON.stringify(value));
          return true;
        } catch (retryErr) {
          console.error('[StorageService] Write failed after cache eviction, falling back to memory store:', retryErr);
          this.memoryFallback.set(key, value);
          return false;
        }
      }

      console.error(`[StorageService] Error setting key "${key}":`, err);
      this.memoryFallback.set(key, value);
      return false;
    }
  }

  public removeLocal(key: string): void {
    const ls = this.localStorage;
    if (ls && typeof ls.removeItem === 'function') {
      try {
        ls.removeItem(key);
      } catch (err) {
        console.error(`[StorageService] Error removing key "${key}":`, err);
      }
    }
    this.memoryFallback.delete(key);
  }

  public clearAllLocal(): void {
    const ls = this.localStorage;
    if (ls && typeof ls.clear === 'function') {
      try {
        ls.clear();
      } catch (err) {
        console.error('[StorageService] Error clearing localStorage:', err);
      }
    }
    this.memoryFallback.clear();
  }

  private autoRepairCorruptLocalKey(key: string): void {
    const ls = this.localStorage;
    if (!ls || typeof ls.getItem !== 'function' || typeof ls.setItem !== 'function' || typeof ls.removeItem !== 'function') return;
    try {
      const rawCorrupt = ls.getItem(key);
      if (rawCorrupt) {
        const backupKey = `__corrupted_${key}_${Date.now()}`;
        ls.setItem(backupKey, rawCorrupt);
        console.warn(`[StorageService] Corrupted data backed up to "${backupKey}" and reset.`);
      }
      ls.removeItem(key);
    } catch (repairErr) {
      console.error('[StorageService] Failed to auto-repair corrupt key:', repairErr);
    }
  }

  private evictTemporaryCaches(): void {
    const ls = this.localStorage;
    if (!ls || typeof ls.key !== 'function' || typeof ls.removeItem !== 'function') return;
    try {
      const keysToRemove: string[] = [];
      const len = typeof ls.length === 'number' ? ls.length : 0;
      for (let i = 0; i < len; i++) {
        const key = ls.key(i);
        if (key) {
          // Remove query caches and old corrupted backups
          if (
            key.startsWith('__corrupted_') ||
            key.startsWith('cache_') ||
            key.startsWith('query_cache_') ||
            key.includes('_temp_')
          ) {
            keysToRemove.push(key);
          }
        }
      }
      keysToRemove.forEach((k) => {
        try {
          ls.removeItem(k);
        } catch {}
      });
    } catch (e) {
      console.error('[StorageService] Cache eviction error:', e);
    }
  }

  // ==========================================
  // Asynchronous IndexedDB Tier
  // ==========================================

  public async getIDBDatabase(): Promise<IDBDatabase | null> {
    if (typeof window === 'undefined' || !window.indexedDB) {
      return null;
    }
    if (this.dbPromise) return this.dbPromise;

    this.dbPromise = new Promise<IDBDatabase | null>((resolve) => {
      try {
        const request = window.indexedDB.open(DB_NAME, DB_VERSION);

        request.onupgradeneeded = (event: IDBVersionChangeEvent) => {
          const db = (event.target as IDBOpenDBRequest).result;
          // Create object stores if not existing
          if (!db.objectStoreNames.contains(IDB_STORES.TICKETS)) {
            db.createObjectStore(IDB_STORES.TICKETS, { keyPath: 'ticketId' });
          }
          if (!db.objectStoreNames.contains(IDB_STORES.OFFLINE_VIDEOS)) {
            db.createObjectStore(IDB_STORES.OFFLINE_VIDEOS, { keyPath: 'id' });
          }
          if (!db.objectStoreNames.contains(IDB_STORES.MEDIA_BLOBS)) {
            db.createObjectStore(IDB_STORES.MEDIA_BLOBS, { keyPath: 'key' });
          }
          if (!db.objectStoreNames.contains(IDB_STORES.METADATA)) {
            db.createObjectStore(IDB_STORES.METADATA, { keyPath: 'key' });
          }
        };

        request.onsuccess = () => {
          resolve(request.result);
        };

        request.onerror = () => {
          console.warn('[StorageService] IndexedDB open error, using memory fallback:', request.error);
          resolve(null);
        };
      } catch (err) {
        console.warn('[StorageService] IndexedDB unavailable, using memory fallback:', err);
        resolve(null);
      }
    });

    return this.dbPromise;
  }

  public async getIDB<T>(storeName: IDBStoreName, key: IDBValidKey): Promise<T | null> {
    const db = await this.getIDBDatabase();
    if (!db) {
      const memKey = `idb_${storeName}_${String(key)}`;
      return this.memoryFallback.has(memKey) ? (this.memoryFallback.get(memKey) as T) : null;
    }

    return new Promise((resolve) => {
      try {
        const tx = db.transaction(storeName, 'readonly');
        const store = tx.objectStore(storeName);
        const req = store.get(key);

        req.onsuccess = () => {
          resolve(req.result !== undefined ? req.result : null);
        };

        req.onerror = () => {
          console.warn(`[StorageService] Error reading key "${String(key)}" from store "${storeName}":`, req.error);
          resolve(null);
        };
      } catch (err) {
        console.warn(`[StorageService] Transaction error on store "${storeName}":`, err);
        resolve(null);
      }
    });
  }

  public async setIDB<T extends Record<string, any>>(storeName: IDBStoreName, value: T): Promise<boolean> {
    const db = await this.getIDBDatabase();
    if (!db) {
      // Determine key path
      const keyProp = storeName === IDB_STORES.TICKETS ? 'ticketId' : storeName === IDB_STORES.OFFLINE_VIDEOS ? 'id' : 'key';
      const keyVal = value[keyProp] || String(Date.now());
      const memKey = `idb_${storeName}_${keyVal}`;
      this.memoryFallback.set(memKey, value);
      return true;
    }

    return new Promise((resolve) => {
      try {
        const tx = db.transaction(storeName, 'readwrite');
        const store = tx.objectStore(storeName);
        const req = store.put(value);

        req.onsuccess = () => resolve(true);
        req.onerror = () => {
          console.warn(`[StorageService] Error putting record into store "${storeName}":`, req.error);
          resolve(false);
        };
      } catch (err) {
        console.warn(`[StorageService] Transaction error on store "${storeName}":`, err);
        resolve(false);
      }
    });
  }

  public async removeIDB(storeName: IDBStoreName, key: IDBValidKey): Promise<boolean> {
    const db = await this.getIDBDatabase();
    if (!db) {
      const memKey = `idb_${storeName}_${String(key)}`;
      this.memoryFallback.delete(memKey);
      return true;
    }

    return new Promise((resolve) => {
      try {
        const tx = db.transaction(storeName, 'readwrite');
        const store = tx.objectStore(storeName);
        const req = store.delete(key);

        req.onsuccess = () => resolve(true);
        req.onerror = () => {
          console.warn(`[StorageService] Error deleting key "${String(key)}" from store "${storeName}":`, req.error);
          resolve(false);
        };
      } catch (err) {
        console.warn(`[StorageService] Transaction error on store "${storeName}":`, err);
        resolve(false);
      }
    });
  }

  public async getAllIDB<T>(storeName: IDBStoreName): Promise<T[]> {
    const db = await this.getIDBDatabase();
    if (!db) {
      const prefix = `idb_${storeName}_`;
      const results: T[] = [];
      this.memoryFallback.forEach((val, k) => {
        if (k.startsWith(prefix)) {
          results.push(val as T);
        }
      });
      return results;
    }

    return new Promise((resolve) => {
      try {
        const tx = db.transaction(storeName, 'readonly');
        const store = tx.objectStore(storeName);
        const req = store.getAll();

        req.onsuccess = () => {
          resolve(req.result || []);
        };

        req.onerror = () => {
          console.warn(`[StorageService] Error getting all from store "${storeName}":`, req.error);
          resolve([]);
        };
      } catch (err) {
        console.warn(`[StorageService] Transaction error on store "${storeName}":`, err);
        resolve([]);
      }
    });
  }
}

export const storageService = new StorageService();

storage.ticket_store_full:
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { AspectRatioMode, FramingRuleMode, useCineMorphStore } from './useCineMorphStore';
import { storageService, IDB_STORES } from '../services/storageService';

export interface MovieTicket {
  ticketId: string;
  movieTitle: string;
  sourceUrl: string;
  isLocal: boolean;
  aspectRatio: AspectRatioMode;
  framingRule: FramingRuleMode;
  timestampSeconds: number;
  durationSeconds: number;
  printedAt: number;
  thumbnailDataUrl?: string;
  seatAssignment?: string;
}

export interface TicketStoreState {
  tickets: MovieTicket[];
  isPrintingAnimationActive: boolean;
  animationCountdownSeconds: number;
  activeTicket: MovieTicket | null;
  saveTicketProgress: (ticket: Omit<MovieTicket, 'ticketId' | 'printedAt'>) => string;
  resumeFromTicket: (ticketId: string) => MovieTicket | null;
  removeTicket: (ticketId: string) => void;
  trigger10sPrintAnimation: (movie: {
    title: string;
    source: string;
    isLocal: boolean;
    file?: File;
  }) => Promise<void>;
  cancelPrintAnimation: () => void;
}

const STORAGE_KEY_TICKETS = 'omnistream-tickets-store';

function generateSeatAssignment(): string {
  const rows = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
  const row = rows[Math.floor(Math.random() * rows.length)];
  const seat = Math.floor(Math.random() * 18) + 1;
  return `ROW ${row} • SEAT ${seat}`;
}

export const useTicketStore = create<TicketStoreState>()(
  persist(
    (set, get) => ({
      tickets: [],
      isPrintingAnimationActive: false,
      animationCountdownSeconds: 0,
      activeTicket: null,

      saveTicketProgress: (ticketData: Omit<MovieTicket, 'ticketId' | 'printedAt'>): string => {
        const existing = get().tickets;
        const existingIndex = existing.findIndex(
          (t) => t.sourceUrl === ticketData.sourceUrl || (t.movieTitle === ticketData.movieTitle && t.isLocal === ticketData.isLocal)
        );

        let ticketId: string;
        let updatedTickets: MovieTicket[];

        if (existingIndex >= 0) {
          ticketId = existing[existingIndex].ticketId;
          const updatedTicket: MovieTicket = {
            ...existing[existingIndex],
            ...ticketData,
            ticketId,
            printedAt: Date.now(),
          };
          updatedTickets = [
            updatedTicket,
            ...existing.filter((_, idx) => idx !== existingIndex),
          ];
        } else {
          ticketId = `ticket_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
          const newTicket: MovieTicket = {
            ...ticketData,
            ticketId,
            printedAt: Date.now(),
            seatAssignment: ticketData.seatAssignment || generateSeatAssignment(),
          };
          updatedTickets = [newTicket, ...existing];
        }

        // Asynchronously persist heavy record to IndexedDB
        try {
          storageService.setIDB(IDB_STORES.TICKETS, updatedTickets[0]);
        } catch (e) {}

        set({
          tickets: updatedTickets,
          activeTicket: updatedTickets[0],
        });

        return ticketId;
      },

      resumeFromTicket: (ticketId: string): MovieTicket | null => {
        const ticket = get().tickets.find((t) => t.ticketId === ticketId);
        if (!ticket) return null;

        set({ activeTicket: ticket });

        // Sync with CineMorph store
        const cineMorph = useCineMorphStore.getState();
        cineMorph.setVideoSource({
          type: ticket.isLocal ? 'local' : 'youtube',
          url: ticket.sourceUrl,
          name: ticket.movieTitle,
          thumbnailUrl: ticket.thumbnailDataUrl,
          duration: ticket.durationSeconds,
        });
        cineMorph.setAspectRatio(ticket.aspectRatio);
        cineMorph.setFramingRule(ticket.framingRule);
        cineMorph.setPlaybackTimestamp(ticket.timestampSeconds);
        cineMorph.setIsPlaying(true);

        return ticket;
      },

      removeTicket: (ticketId: string) => {
        const updated = get().tickets.filter((t) => t.ticketId !== ticketId);
        try {
          storageService.removeIDB(IDB_STORES.TICKETS, ticketId);
        } catch (e) {}

        set({
          tickets: updated,
          activeTicket: get().activeTicket?.ticketId === ticketId ? null : get().activeTicket,
        });
      },

      trigger10sPrintAnimation: async (movie: {
        title: string;
        source: string;
        isLocal: boolean;
        file?: File;
      }) => {
        set({
          isPrintingAnimationActive: true,
          animationCountdownSeconds: 10,
        });

        // Dispatch heads-up event for background pre-processing
        if (typeof window !== 'undefined') {
          try {
            window.dispatchEvent(
              new CustomEvent('omnistream:heads-up:start', {
                detail: { movie },
              })
            );
          } catch (e) {}
        }

        // Run countdown timer
        const timerDurationMs = 10000;
        const intervalMs = 1000;
        let elapsed = 0;

        await new Promise<void>((resolve) => {
          const interval = setInterval(() => {
            elapsed += intervalMs;
            const remaining = Math.max(0, 10 - Math.floor(elapsed / 1000));
            set({ animationCountdownSeconds: remaining });

            if (elapsed >= timerDurationMs) {
              clearInterval(interval);
              resolve();
            }
          }, intervalMs);
        });

        // Auto-save and register the torn ticket
        const cineMorph = useCineMorphStore.getState();
        const ticketId = get().saveTicketProgress({
          movieTitle: movie.title,
          sourceUrl: movie.source,
          isLocal: movie.isLocal,
          aspectRatio: cineMorph.aspectRatio,
          framingRule: cineMorph.framingRule,
          timestampSeconds: 0,
          durationSeconds: 0,
        });

        const createdTicket = get().tickets.find((t) => t.ticketId === ticketId) || null;

        set({
          isPrintingAnimationActive: false,
          animationCountdownSeconds: 0,
          activeTicket: createdTicket,
        });

        // Load media into CineMorph player
        cineMorph.setVideoSource({
          type: movie.isLocal ? 'local' : 'youtube',
          url: movie.source,
          file: movie.file,
          name: movie.title,
        });
        cineMorph.setIsPlaying(true);
      },

      cancelPrintAnimation: () => {
        set({
          isPrintingAnimationActive: false,
          animationCountdownSeconds: 0,
        });
      },
    }),
    {
      name: STORAGE_KEY_TICKETS,
      storage: {
        getItem: (name) => {
          const val = storageService.getLocal<any>(name, null);
          return val ? { state: val } : null;
        },
        setItem: (name, value) => {
          storageService.setLocal(name, value.state);
        },
        removeItem: (name) => {
          storageService.removeLocal(name);
        },
      },
    }
  )
);

