import { describe, it, expect, beforeEach } from 'vitest';
import { useAppStore } from '../../store';
import { MOCK_CHANNELS, MOCK_LOCAL_MEDIA, MOCK_VIDEOS } from '../helpers/fixtures';

describe('Tier 1: Local Storage Persistence (F11)', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('T1-STOR-01: subscriptions persist to localStorage under cinemorph-utube-storage key', () => {
    useAppStore.getState().subscribe(MOCK_CHANNELS[0]);

    const stored = localStorage.getItem('cinemorph-utube-storage');
    expect(stored).not.toBeNull();
    const parsed = JSON.parse(stored || '{}');
    expect(parsed.state?.subscriptions).toBeDefined();
    expect(parsed.state.subscriptions.some((s: any) => s.id === MOCK_CHANNELS[0].id)).toBe(true);
  });

  it('T1-STOR-02: search history records and updates survive in localStorage', () => {
    useAppStore.getState().addSearchHistory('imax 70mm 4k');
    useAppStore.getState().addSearchHistory('react state management');

    const stored = localStorage.getItem('cinemorph-utube-storage');
    const parsed = JSON.parse(stored || '{}');
    expect(parsed.state.searchHistory).toContain('imax 70mm 4k');
    expect(parsed.state.searchHistory).toContain('react state management');
  });

  it('T1-STOR-03: video watch history progress persists to localStorage', () => {
    useAppStore.getState().addToHistory(MOCK_VIDEOS[0], 450, 900);

    const stored = localStorage.getItem('cinemorph-utube-storage');
    const parsed = JSON.parse(stored || '{}');
    const historyItem = parsed.state.history?.[MOCK_VIDEOS[0].id];
    expect(historyItem).toBeDefined();
    expect(historyItem.progress).toBe(450);
  });

  it('T1-STOR-04: local media history items persist across storage serialization', () => {
    useAppStore.getState().addLocalMediaToHistory(MOCK_LOCAL_MEDIA);

    const stored = localStorage.getItem('cinemorph-utube-storage');
    const parsed = JSON.parse(stored || '{}');
    const localItem = parsed.state.localMediaHistory?.[MOCK_LOCAL_MEDIA.id];
    expect(localItem).toBeDefined();
    expect(localItem.name).toBe(MOCK_LOCAL_MEDIA.name);
  });

  it('T1-STOR-05: audio EQ configuration persists across storage serialization', () => {
    useAppStore.getState().setAudioEQ({
      preset: 'bass-heavy',
      bassBoost: 10,
      dialogueClarity: 5,
      surround3D: true,
    });

    const stored = localStorage.getItem('cinemorph-utube-storage');
    const parsed = JSON.parse(stored || '{}');
    expect(parsed.state.audioEQ?.preset).toBe('bass-heavy');
    expect(parsed.state.audioEQ?.bassBoost).toBe(10);
  });

  it('T1-STOR-06: clearing history cleans localStorage representation', () => {
    useAppStore.getState().addToHistory(MOCK_VIDEOS[1], 100, 500);
    useAppStore.getState().clearHistory();

    const stored = localStorage.getItem('cinemorph-utube-storage');
    const parsed = JSON.parse(stored || '{}');
    expect(Object.keys(parsed.state?.history || {})).toHaveLength(0);
  });
});

utube.search_service_full:
import { Video } from '../../types';
import { searchVideos, getVideosByIds } from '../youtube';
import { cacheService } from './cacheService';

/**
 * Search Service - Intelligent relevance ranking and candidate discovery engine.
 */

export interface RankedVideoCandidate {
  video: Video;
  relevanceScore: number;
}

export function computeRelevanceScore(query: string, video: Video): number {
  const qTerms = query.toLowerCase().split(/\s+/).filter(t => t.length > 1);
  if (qTerms.length === 0) return 50;

  const titleLower = video.title.toLowerCase();
  const descLower = (video.description || '').toLowerCase();
  const channelLower = (video.channelTitle || '').toLowerCase();

  let score = 0;

  // Title term match (highest weight)
  qTerms.forEach(term => {
    if (titleLower.includes(term)) score += 35;
    if (descLower.includes(term)) score += 15;
    if (channelLower.includes(term)) score += 20;
  });

  // Exact full query title match bonus
  if (titleLower.includes(query.toLowerCase())) {
    score += 50;
  }

  // View count popularity bonus
  const views = parseInt(video.viewCount || '0', 10);
  if (views > 1000000) score += 15;
  else if (views > 100000) score += 10;

  return score;
}

export async function searchAndRankVideos(query: string): Promise<Video[]> {
  const trimmed = query.trim();
  if (!trimmed) return [];

  // Check fast cache
  const cached = cacheService.get(trimmed);
  if (cached && cached.length > 0) {
    return cached;
  }

  // Fetch search candidates
  const response = await searchVideos(trimmed, 'video');
  const candidateResults = response.results;

  if (candidateResults.length === 0) return [];

  const videoIds = candidateResults.map(r => r.id);
  const fullVideos = await getVideosByIds(videoIds);

  // Compute relevance score & sort
  const ranked = fullVideos
    .map(video => ({
      video,
      relevanceScore: computeRelevanceScore(trimmed, video)
    }))
    .sort((a, b) => b.relevanceScore - a.relevanceScore)
    .map(r => r.video);

  // Cache sorted results
  cacheService.set(trimmed, ranked);

  return ranked;
}

utube.cache_manager_full:
import { Video } from '../../types';

/**
 * Two-Tier Cache System (Query Cache + Video Metadata Cache) with In-Flight Request Deduplication.
 */

interface CacheRecord<T> {
  data: T;
  timestamp: number;
  ttl?: number;
}

class CacheManager {
  private queryCache = new Map<string, CacheRecord<string[]>>();
  private metadataCache = new Map<string, CacheRecord<Video>>();
  private genericCache = new Map<string, CacheRecord<any>>();
  private inFlightRequests = new Map<string, Promise<any>>();
  private readonly QUERY_TTL = 1000 * 60 * 30; // 30 mins
  private readonly METADATA_TTL = 1000 * 60 * 60 * 2; // 2 hours

  // Generic Namespaced Cache Accessors
  public set(namespace: string, key: string, value: any, ttlMs?: number): void {
    const cacheKey = `${namespace}:${key}`;
    this.genericCache.set(cacheKey, { data: value, timestamp: Date.now(), ttl: ttlMs });
  }

  public get(namespace: string, key: string): any | null {
    const cacheKey = `${namespace}:${key}`;
    const entry = this.genericCache.get(cacheKey);
    if (!entry) return null;
    const ttl = entry.ttl ?? this.QUERY_TTL;
    if (Date.now() - entry.timestamp > ttl) {
      this.genericCache.delete(cacheKey);
      return null;
    }
    return entry.data;
  }

  public clear(namespace?: string): void {
    if (!namespace) {
      this.clearAll();
      return;
    }
    const prefix = `${namespace}:`;
    for (const k of Array.from(this.genericCache.keys())) {
      if (k.startsWith(prefix)) {
        this.genericCache.delete(k);
      }
    }
  }

  // Query Cache Accessors
  public getCachedQueryCandidates(query: string): string[] | null {
    const key = query.trim().toLowerCase();
    const entry = this.queryCache.get(key);
    if (entry && Date.now() - entry.timestamp < this.QUERY_TTL) {
      return entry.data;
    }
    return null;
  }

  public setCachedQueryCandidates(query: string, videoIds: string[]): void {
    const key = query.trim().toLowerCase();
    this.queryCache.set(key, { data: videoIds, timestamp: Date.now() });
  }

  // Video Metadata Cache Accessors
  public getCachedVideoMetadata(videoId: string): Video | null {
    const entry = this.metadataCache.get(videoId);
    if (entry && Date.now() - entry.timestamp < this.METADATA_TTL) {
      return entry.data;
    }
    return null;
  }

  public setCachedVideoMetadata(video: Video): void {
    this.metadataCache.set(video.id, { data: video, timestamp: Date.now() });
  }

  // In-Flight Request Deduplication
  public deduplicateRequest<T>(requestKey: string, fetchFn: () => Promise<T>): Promise<T> {
    const key = requestKey.trim().toLowerCase();

    if (this.inFlightRequests.has(key)) {
      console.log(`[CacheManager] In-flight deduplication hit for key: "${key}"`);
      return this.inFlightRequests.get(key)! as Promise<T>;
    }

    const promise = fetchFn().finally(() => {
      this.inFlightRequests.delete(key);
    });

    this.inFlightRequests.set(key, promise);
    return promise;
  }

  // Background TTL Garbage Collector
  public pruneExpired(): void {
    const now = Date.now();
    for (const [key, record] of this.queryCache.entries()) {
      if (now - record.timestamp >= this.QUERY_TTL) {
        this.queryCache.delete(key);
      }
    }
    for (const [key, record] of this.metadataCache.entries()) {
      if (now - record.timestamp >= this.METADATA_TTL) {
        this.metadataCache.delete(key);
      }
    }
  }

  public clearAll(): void {
    this.queryCache.clear();
    this.metadataCache.clear();
    this.inFlightRequests.clear();
  }
}

export const cacheManager = new CacheManager();

// Automatically schedule periodic background cache pruning
if (typeof window !== 'undefined') {
  setInterval(() => {
    if ('requestIdleCallback' in window) {
      (window as any).requestIdleCallback(() => cacheManager.pruneExpired());
    } else {
      cacheManager.pruneExpired();
    }
  }, 1000 * 60 * 10); // Every 10 mins
}

utube.recommendations_full:
import { Video, Channel, HistoryItem, Collection } from '../types';

export interface UserStats {
  totalWatched: number;
  totalHours: number;
  completedCount: number;
  completionRate: number;
  subscriptionsCount: number;
  collectionsCount: number;
  topChannels: { channelTitle: string; count: number }[];
}

export function calculateUserStats(
  history: Record<string, HistoryItem>,
  subscriptions: Channel[],
  collections: Collection[]
): UserStats {
  const historyItems = Object.values(history);
  const totalWatched = historyItems.length;
  
  let totalSeconds = 0;
  let completedCount = 0;
  const channelCounts: Record<string, number> = {};

  historyItems.forEach(item => {
    totalSeconds += item.progress || 0;
    const isCompleted = item.duration && item.progress >= item.duration * 0.95;
    if (isCompleted) completedCount++;

    const chan = item.video.channelTitle || 'Unknown';
    channelCounts[chan] = (channelCounts[chan] || 0) + 1;
  });

  const topChannels = Object.entries(channelCounts)
    .map(([channelTitle, count]) => ({ channelTitle, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);

  const totalHours = parseFloat((totalSeconds / 3600).toFixed(1));
  const completionRate = totalWatched > 0 ? Math.round((completedCount / totalWatched) * 100) : 0;

  return {
    totalWatched,
    totalHours,
    completedCount,
    completionRate,
    subscriptionsCount: subscriptions.length,
    collectionsCount: collections.length,
    topChannels,
  };
}

export function getRecommendedVideos(
  popularVideos: Video[],
  history: Record<string, HistoryItem>,
  subscriptions: Channel[],
  collections: Collection[],
  searchHistory: string[] = []
): Video[] {
  if (popularVideos.length === 0) return [];

  const historyItems = Object.values(history);
  const subscribedChannelIds = new Set(subscriptions.map(s => s.id));
  const watchedVideoIds = new Set(historyItems.map(h => h.video.id));
  
  // Extract keywords from history, collections, and search history
  const keywordMap: Record<string, number> = {};
  const sampleVideos = [
    ...historyItems.map(h => h.video),
    ...collections.flatMap(c => c.videos)
  ];

  sampleVideos.forEach(v => {
    const words = (v.title || '').toLowerCase().replace(/[^\w\s]/gi, '').split(/\s+/);
    words.forEach(w => {
      if (w.length > 3 && !['with', 'from', 'that', 'this', 'have', 'what', 'your', 'video'].includes(w)) {
        keywordMap[w] = (keywordMap[w] || 0) + 1;
      }
    });
  });

  // Include recent search history query terms in keyword map
  searchHistory.forEach(query => {
    const words = query.toLowerCase().replace(/[^\w\s]/gi, '').split(/\s+/);
    words.forEach(w => {
      if (w.length > 2) {
        keywordMap[w] = (keywordMap[w] || 0) + 3;
      }
    });
  });

  // Calculate score for each candidate video
  const scoredVideos = popularVideos.map(video => {
    let score = 0;

    // Penalty for videos already fully watched
    if (watchedVideoIds.has(video.id)) {
      score -= 100;
    }

    // Boost if from a subscribed channel
    if (subscribedChannelIds.has(video.channelId)) {
      score += 50;
    }

    // Boost based on title keyword relevance
    const videoWords = (video.title || '').toLowerCase().replace(/[^\w\s]/gi, '').split(/\s+/);
    videoWords.forEach(w => {
      if (keywordMap[w]) {
        score += keywordMap[w] * 5;
      }
    });

    // Boost for newer videos
    const publishDate = new Date(video.publishedAt).getTime();
    const daysOld = (Date.now() - publishDate) / (1000 * 60 * 60 * 24);
    if (daysOld < 7) {
      score += 15;
    }

    return { video, score };
  });

  // Sort descending by recommendation score
  scoredVideos.sort((a, b) => b.score - a.score);

  return scoredVideos.map(item => item.video);
}

utube.utube_store_full:
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { searchVideos, FALLBACK_VIDEOS } from '../lib/youtube';
import { getRecommendedVideos } from '../lib/recommendations';
import { storageService } from '../services/storageService';

export interface UTubeVideo {
  id: string;
  title: string;
  channelTitle: string;
  thumbnailUrl: string;
  duration?: string;
  publishedAt?: string;
  views?: string;
}

export interface ChannelSubscription {
  channelId: string;
  channelTitle: string;
  avatarUrl: string;
  subscribedAt: number;
}

export interface UTubeStoreState {
  searchResults: UTubeVideo[];
  subscriptions: ChannelSubscription[];
  recentSearches: string[];
  recommendedVideos: UTubeVideo[];
  subscribedFeed: UTubeVideo[];
  lastFeedRefresh: number; // timestamp ms (4-hour refresh threshold)
  currentVideo: UTubeVideo | null;
  search: (query: string) => Promise<UTubeVideo[]>; // Returns exactly 3
  subscribe: (channel: ChannelSubscription) => void;
  unsubscribe: (channelId: string) => void;
  extractRecommendations: () => void; // 5 videos based on recent searches
  refreshFeedIfNeeded: () => Promise<void>;
  playVideo: (video: UTubeVideo | string) => void;
}

const STORAGE_KEY_UTUBE = 'omnistream-utube-store';
const FOUR_HOURS_MS = 4 * 60 * 60 * 1000;

export const useUTubeStore = create<UTubeStoreState>()(
  persist(
    (set, get) => ({
      searchResults: [],
      subscriptions: [],
      recentSearches: [],
      recommendedVideos: [],
      subscribedFeed: [],
      lastFeedRefresh: 0,
      currentVideo: null,

      search: async (query: string): Promise<UTubeVideo[]> => {
        const trimmed = query.trim();
        if (!trimmed) {
          set({ searchResults: [] });
          return [];
        }

        // Add to recent searches (deduplicated, max 10)
        const currentSearches = get().recentSearches;
        const updatedSearches = [
          trimmed,
          ...currentSearches.filter((s) => s.toLowerCase() !== trimmed.toLowerCase()),
        ].slice(0, 10);

        try {
          const res = await searchVideos(trimmed, 'video');
          // Guarantee exactly top 3 results
          const rawTop3 = (res.results || []).slice(0, 3);
          const mapped: UTubeVideo[] = rawTop3.map((r) => ({
            id: r.id,
            title: r.title,
            channelTitle: r.channelTitle,
            thumbnailUrl: r.thumbnails?.medium || r.thumbnails?.high || `https://i.ytimg.com/vi/${r.id}/mqdefault.jpg`,
            duration: 'PT10M00S',
            publishedAt: r.publishedAt,
            views: '1000000',
          }));

          // If fewer than 3 were returned from search, fill from FALLBACK_VIDEOS
          if (mapped.length < 3) {
            for (const fallback of FALLBACK_VIDEOS) {
              if (mapped.length >= 3) break;
              if (!mapped.some((m) => m.id === fallback.id)) {
                mapped.push({
                  id: fallback.id,
                  title: fallback.title,
                  channelTitle: fallback.channelTitle,
                  thumbnailUrl: fallback.thumbnails.medium,
                  duration: fallback.duration,
                  publishedAt: fallback.publishedAt,
                  views: fallback.viewCount,
                });
              }
            }
          }

          set({
            searchResults: mapped,
            recentSearches: updatedSearches,
          });

          // Trigger recommendations update based on new search
          get().extractRecommendations();

          return mapped;
        } catch (err) {
          console.error('[useUTubeStore] Search error:', err);
          // Fallback to top 3 from FALLBACK_VIDEOS
          const fallbackTop3: UTubeVideo[] = FALLBACK_VIDEOS.slice(0, 3).map((f) => ({
            id: f.id,
            title: f.title,
            channelTitle: f.channelTitle,
            thumbnailUrl: f.thumbnails.medium,
            duration: f.duration,
            publishedAt: f.publishedAt,
            views: f.viewCount,
          }));

          set({
            searchResults: fallbackTop3,
            recentSearches: updatedSearches,
          });

          return fallbackTop3;
        }
      },

      subscribe: (channel: ChannelSubscription) => {
        set((state) => {
          if (state.subscriptions.some((s) => s.channelId === channel.channelId)) {
            return state;
          }
          return {
            subscriptions: [...state.subscriptions, channel],
          };
        });
      },

      unsubscribe: (channelId: string) => {
        set((state) => ({
          subscriptions: state.subscriptions.filter((s) => s.channelId !== channelId),
        }));
      },

      extractRecommendations: () => {
        const searches = get().recentSearches;
        const subs = get().subscriptions.map((s) => ({
          id: s.channelId,
          title: s.channelTitle,
          description: '',
          thumbnails: { default: s.avatarUrl, medium: s.avatarUrl, high: s.avatarUrl },
        }));

        const recs = getRecommendedVideos(FALLBACK_VIDEOS, {}, subs, [], searches);
        // Guarantee exactly 5 recommendations
        const top5: UTubeVideo[] = recs.slice(0, 5).map((v) => ({
          id: v.id,
          title: v.title,
          channelTitle: v.channelTitle,
          thumbnailUrl: v.thumbnails?.medium || v.thumbnails?.high || '',
          duration: v.duration,
          publishedAt: v.publishedAt,
          views: v.viewCount,
        }));

        // If fewer than 5, backfill from FALLBACK_VIDEOS
        while (top5.length < 5 && top5.length < FALLBACK_VIDEOS.length) {
          const nextFallback = FALLBACK_VIDEOS[top5.length];
          top5.push({
            id: nextFallback.id,
            title: nextFallback.title,
            channelTitle: nextFallback.channelTitle,
            thumbnailUrl: nextFallback.thumbnails.medium,
            duration: nextFallback.duration,
            publishedAt: nextFallback.publishedAt,
            views: nextFallback.viewCount,
          });
        }

        set({ recommendedVideos: top5 });
      },

      refreshFeedIfNeeded: async () => {
        const now = Date.now();
        const { lastFeedRefresh, subscriptions } = get();

        if (now - lastFeedRefresh >= FOUR_HOURS_MS || (get().subscribedFeed.length === 0 && subscriptions.length > 0)) {
          const feedVideos: UTubeVideo[] = [];
          for (const sub of subscriptions) {
            feedVideos.push({
              id: `feed_${sub.channelId}_${now}`,
              title: `Latest from ${sub.channelTitle}`,
              channelTitle: sub.channelTitle,
              thumbnailUrl: sub.avatarUrl,
              publishedAt: new Date(now).toISOString(),
              views: '50000',
            });
          }

          set({
            subscribedFeed: feedVideos,
            lastFeedRefresh: now,
          });
        }
      },

      playVideo: (video: UTubeVideo | string) => {
        if (typeof video === 'string') {
          const matched = FALLBACK_VIDEOS.find((v) => v.id === video);
          if (matched) {
            set({
              currentVideo: {
                id: matched.id,
                title: matched.title,
                channelTitle: matched.channelTitle,
                thumbnailUrl: matched.thumbnails?.medium || '',
                duration: matched.duration,
                publishedAt: matched.publishedAt,
                views: matched.viewCount,
              },
            });
          } else {
            set({
              currentVideo: {
                id: video,
                title: `Direct Playback (${video})`,
                channelTitle: 'YouTube Stream',
                thumbnailUrl: `https://i.ytimg.com/vi/${video}/mqdefault.jpg`,
              },
            });
          }
        } else {
          set({ currentVideo: video });
        }
      },
    }),
    {
      name: STORAGE_KEY_UTUBE,
      storage: {
        getItem: (name) => {
          const val = storageService.getLocal<any>(name, null);
          return val ? { state: val } : null;
        },
        setItem: (name, value) => {
          storageService.setLocal(name, value.state);
        },
        removeItem: (name) => {
          storageService.removeLocal(name);
        },
      },
    }
  )
);
